import{_ as e,o,c as a,a2 as r}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"Capturing traffic","description":"","frontmatter":{},"headers":[],"relativePath":"guide/capture.md","filePath":"guide/capture.md","lastUpdated":1787871741000}'),s={name:"guide/capture.md"};function i(l,t,n,d,c,h){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="capturing-traffic" tabindex="-1">Capturing traffic <a class="header-anchor" href="#capturing-traffic" aria-label="Permalink to &quot;Capturing traffic&quot;">​</a></h1><h2 id="start-and-stop" tabindex="-1">Start and stop <a class="header-anchor" href="#start-and-stop" aria-label="Permalink to &quot;Start and stop&quot;">​</a></h2><p>Use the <strong>Capture</strong> button in the command bar. The status dot turns green and pulses while capturing, and the bar shows the proxy port, request count, and failure count.</p><p>Behind the scenes, starting a capture:</p><ol><li>Runs <code>adb root</code> on the target emulator</li><li>Installs the Beholder CA as a system certificate — through a tmpfs mount bound over the Conscrypt apex on Android 14+, with correct SELinux contexts and zygote propagation</li><li>Starts a local MITM proxy on a random port</li><li>Sets the emulator global proxy to <code>10.0.2.2:&lt;port&gt;</code></li></ol><h2 id="the-request-list" tabindex="-1">The request list <a class="header-anchor" href="#the-request-list" aria-label="Permalink to &quot;The request list&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Column</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Method</strong></td><td>Color-coded HTTP method</td></tr><tr><td><strong>Endpoint</strong></td><td><code>host/path</code> — collapses to path only when you filter to a single domain</td></tr><tr><td><strong>St</strong></td><td>Status code, colored by class; a spinner dot while in flight</td></tr><tr><td><strong>Time</strong></td><td>Total milliseconds; amber or red when over your slow threshold</td></tr><tr><td><strong>Size</strong></td><td>Response or request body size</td></tr></tbody></table><p>Rows with errors get a red left bar. New requests flash briefly.</p><h2 id="following-live-traffic" tabindex="-1">Following live traffic <a class="header-anchor" href="#following-live-traffic" aria-label="Permalink to &quot;Following live traffic&quot;">​</a></h2><p>Toggle <strong>follow</strong> to keep the list pinned to the newest request. Scrolling up pauses following automatically; a floating pill shows how many new requests arrived and jumps you back.</p><h2 id="filtering" tabindex="-1">Filtering <a class="header-anchor" href="#filtering" aria-label="Permalink to &quot;Filtering&quot;">​</a></h2><ul><li><strong>Search box</strong> — matches host, path, or URL; enable <code>content</code> to also search request and response bodies</li><li><strong>Domain chips</strong> — click to include a single domain, ⌥click to exclude it (kill analytics noise)</li><li><strong>Quick toggles</strong> — <code>failures</code> (4xx/5xx/errors) and <code>slow</code> (over your threshold)</li><li>Filters persist between sessions</li></ul><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>↑</code> / <code>↓</code></td><td>Move selection through requests</td></tr><tr><td><code>⌘F</code> / <code>Ctrl+F</code></td><td>Focus the filter box</td></tr><tr><td><code>Esc</code></td><td>Close the detail pane</td></tr></tbody></table><h2 id="right-click-actions" tabindex="-1">Right-click actions <a class="header-anchor" href="#right-click-actions" aria-label="Permalink to &quot;Right-click actions&quot;">​</a></h2><p>Right-click any request for: Copy URL, Copy as cURL, Copy response body, Copy request body.</p><h2 id="the-detail-pane" tabindex="-1">The detail pane <a class="header-anchor" href="#the-detail-pane" aria-label="Permalink to &quot;The detail pane&quot;">​</a></h2><p>Click a request to open it. Tabs:</p><ul><li><strong>Headers</strong> — collapsible request/response sections; click a name to copy the key, a value to copy the value, or use the per-row menu for <code>name: value</code></li><li><strong>Cookies</strong> — parsed from <code>cookie</code> and <code>set-cookie</code> headers</li><li><strong>Body</strong> — JSON bodies render as a collapsible tree; click any key to copy its JSON path (<code>user.addresses[0].city</code>). Use the header buttons to copy as cURL or copy the body</li><li><strong>Timing</strong> — TTFB, download, and total with slow highlighting</li></ul><h2 id="websockets" tabindex="-1">WebSockets <a class="header-anchor" href="#websockets" aria-label="Permalink to &quot;WebSockets&quot;">​</a></h2><p>The WebSockets view lists connections with a live frame timeline (sent and received directions marked). Frames are virtualized, so thousands of frames stay smooth.</p><div class="info custom-block"><p class="custom-block-title">WebSocket close events</p><p>Android does not expose a close callback through the proxy layer, so connections may keep showing as open after they end.</p></div>',22)])])}const g=e(s,[["render",i]]);export{p as __pageData,g as default};
